// v16.xx (feeddup), the cloud review (2026-10-15, finding 18): TWO SYSTEMS FOR ONE EVENT MADE TWO LINES. A goal done said GOAL DONE with its
// figure in the detail and also raised a +$ label, which became a second line of the same figure; the team combo said TEAM COMBO and also paid
// a medal of the same name; a three kill burst said TRIPLE KILL and paid the MULTI-KILL medal. Now a figure already written in a line of
// the last 0.8 s is not written again; a medal or a said line that opens like a line of the last 1.2 s is that line, refreshed; and the
// MULTI-KILL medal rides its figure on the streak line it belongs to. feedRecent finds such a line.
function feedRecent(head,age){
  var F=G&&G.fd, i, Ln, h=String(head);
  if(!F) return null;
  for(i=F.lines.length-1;i>=Math.max(0,F.lines.length-4);i--){
    Ln=F.lines[i];
    if(!(F.t-Ln.last<age)||!Ln.segs||!Ln.segs[0]) continue;
    if(Ln.segs[0].t.indexOf(h)===0||h.indexOf(Ln.segs[0].t)===0) return Ln;
  }
  return null;
}
function feedMoney(s){
  var F=feedS(), Ln=F.lines[F.lines.length-1], i, Lj;
  for(i=F.lines.length-1;i>=Math.max(0,F.lines.length-4);i--){ Lj=F.lines[i]; if(F.t-Lj.last<0.8&&(Lj.txt.indexOf(s)>=0||Lj.money===s)) return Lj; }   // v16.xx (feeddup): the figure is already in a line of its own event

function feedMedal(txt,pts){
  var Ln=feedRecent(String(txt),1.2), i, F;
  if(Ln&&(Ln.fk==='medal'||Ln.fk==='ext')){ Ln.at=Ln.last=feedS().t; return Ln; }   // v16.xx (feeddup): the said line and the medal of one event are one line
  if(String(txt)==='MULTI-KILL'){   // v16.xx (feeddup): MULTI-KILL rides on the streak line (TRIPLE KILL and the others) it is the same moment as
    F=feedS(); for(i=F.lines.length-1;i>=Math.max(0,F.lines.length-4);i--){ Ln=F.lines[i]; if(F.t-Ln.last<1.5&&Ln.segs&&Ln.segs[0]&&FEEDMEDALS.test(Ln.segs[0].t)){ Ln.money='+'+arcadeCr(pts); Ln.mf=''; Ln.at=Ln.last=F.t; return Ln; } }
  }
  return feedAdd([{t:String(txt),c:UIC.r_gold},{t:'  +'+arcadeCr(pts),c:UIC.r_gold}],'medal',{});
}

